long enumerate_media_entities(struct media_device *mdev, struct media_entity_desc __user *uent) {
    struct media_entity_desc kent = {0};
    int index = 0;

    if (!mdev || !uent) {
        return -EINVAL;
    }

    while (index < mdev->entity_count) {
        struct media_entity *entity = media_device_get_entity(mdev, index);
        if (!entity) {
            return -ENOENT;
        }

        kent.id = entity->id;
        kent.name = entity->name;
        kent.type = entity->type;
        kent.revision = entity->revision;
        kent.flags = entity->flags;
        kent.group_id = entity->group_id;
        kent.pad_count = entity->num_pads;
        kent.link_count = entity->num_links;

        if (copy_to_user(uent, &kent, sizeof(kent))) {
            return -EFAULT;
        }

        index++;
        uent++;
    }

    return 0;
}
